<?php
namespace App\Controllers\Admin;use App\Support\App;use App\Services\OrderService;
final class OrderController{public function bulk():never{App::requireAdmin();$in=App::input();$ids=array_values(array_unique(array_filter(array_map('intval',(array)($in['ids']??[])))));$status=(string)($in['status']??'');if(!$ids)App::json(['ok'=>false,'message'=>'Pilih order'],422);$ok=[];$failed=[];foreach($ids as $id){try{(new OrderService())->setStatus($id,$status,(string)($in['reason']??''));$ok[]=$id;}catch(\Throwable $e){$failed[]=['id'=>$id,'message'=>$e->getMessage()];}}App::json(['ok'=>!$failed,'updated'=>count($ok),'failed'=>$failed,'message'=>$failed?(count($ok).' berhasil, '.count($failed).' gagal'):(count($ok).' order diperbarui')],$failed?207:200);}}
